import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Build the backdrop stage: vertical gradient plane at z=-2.5
  const stageGeo = new THREE.PlaneGeometry(7, 6);
  const stageMat = new MeshBasicNodeMaterial({
    color: 0x000000,
  });
  stageMat.colorNode = uv().y.mix(
    new THREE.Color(0x0b0b10),
    new THREE.Color(0x16161d)
  );
  const stage = new THREE.Mesh(stageGeo, stageMat);
  stage.position.z = -2.5;
  stage.renderOrder = 0;

  // Root group for this node
  const root = new THREE.Group();
  root.add(stage);

  // Load the hero image and create the textured plane
  const geo = new THREE.PlaneGeometry(3.2, 2);
  const mat = new MeshBasicNodeMaterial();

  const plane = new THREE.Mesh(geo, mat);
  plane.position.copy(
    new THREE.Vector3(
      config.scenePosition?.[0] ?? 0,
      config.scenePosition?.[1] ?? 1.85,
      config.scenePosition?.[2] ?? 0
    )
  );
  plane.renderOrder = 10;

  root.add(plane);

  // Load texture and apply
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      mat.map = texture;
      mat.needsUpdate = true;
    });
  }

  // Create and add the headline text
  const headlineText = ctx.fontAtlas.createText('Atelier Noir — precise · luxury · technical', {
    fontSize: 42,
    color: '#e8ecf2',
    align: 'center',
  });
  headlineText.position.set(0, -1.2, 0.1);
  headlineText.renderOrder = 15;
  root.add(headlineText);

  // Cleanup function
  root.userData.cleanup = () => {
    geo.dispose();
    mat.dispose();
    stageMat.dispose();
    stageGeo.dispose();
  };

  return root;
}
